-- 已退場的欄位不能再被指為問題：清掉退回紀錄裡指向它的問題列，新的 CHECK 才能套上。
DELETE FROM "seller"."kyc_review_issues" WHERE field = 'payout_contact_email';
-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_payout_contact_email_check", DROP CONSTRAINT "kyc_applications_complete_check", ADD CONSTRAINT "kyc_applications_complete_check" CHECK ((status <> ALL (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text])) OR ((submitted_at IS NOT NULL) AND ((pii_purged_at IS NOT NULL) OR ((seller_type = 'INDIVIDUAL'::text) OR ((seller_type = 'COMPANY'::text) AND (company_name IS NOT NULL) AND (tax_id IS NOT NULL)))))), DROP CONSTRAINT "kyc_applications_purged_check", ADD CONSTRAINT "kyc_applications_purged_check" CHECK ((pii_purged_at IS NULL) OR ((real_name IS NULL) AND (birth_date IS NULL) AND (id_card_no_enc IS NULL) AND (id_card_hash IS NULL) AND (id_card_hash_key IS NULL) AND (id_card_issue_date IS NULL) AND (id_card_issue_type IS NULL) AND (id_card_issue_location IS NULL) AND (english_name IS NULL) AND (bank_name IS NULL) AND (bank_code IS NULL) AND (bank_account_enc IS NULL) AND (bank_account_hash IS NULL) AND (bank_account_hash_key IS NULL) AND (website_url IS NULL) AND (company_name IS NULL) AND (tax_id IS NULL) AND (tax_id_hash IS NULL) AND (tax_id_hash_key IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL) AND (rep_id_card_no_enc IS NULL) AND (rep_id_card_hash IS NULL) AND (rep_id_card_hash_key IS NULL))), DROP COLUMN "payout_contact_email";
-- Modify "kyc_review_issues" table
ALTER TABLE "seller"."kyc_review_issues" DROP CONSTRAINT "kyc_review_issues_field_check", ADD CONSTRAINT "kyc_review_issues_field_check" CHECK (field = ANY (ARRAY['real_name'::text, 'birth_date'::text, 'id_card_issue_date'::text, 'id_card_issue_type'::text, 'id_card_issue_location'::text, 'english_name'::text, 'bank_name'::text, 'bank_code'::text, 'bank_account'::text, 'product_type'::text, 'website_url'::text, 'id_card_front'::text, 'id_card_back'::text, 'bank_book'::text, 'individual.id_card_no'::text, 'business.company_name'::text, 'business.tax_id'::text, 'business.company_register_date'::text, 'business.company_address'::text, 'business.company_phone'::text, 'business.rep_id_card_no'::text, 'business.company_documents'::text]));
